}

export type CommunicationsSetupDemoScenario =
  | "ready"
  | "single-number"
  | "empty"
  | "no-voice"
  | "invalid-credentials"
  | "permission-denied"
  | "network-error"
  | "unknown"
  | "failed"
  | "configuring";

export type DemoCommunicationsSetupAdapterOptions = {
  provider?: CommunicationsProvider;
  scenario?: CommunicationsSetupDemoScenario;
  latencyMs?: number;
  now?: () => number;
};

function numbersFor(
